import React from 'react';
import { X } from 'lucide-react';
import ProductImage from './ProductModal/ProductImage';
import ProductDetails from './ProductModal/ProductDetails';

const ProductModal = ({ isOpen, onClose, product }) => {
  if (!isOpen || !product) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black bg-opacity-70"
        onClick={onClose}
      ></div>
      
      {/* Modal Content */}
      <div className="relative bg-white rounded-lg max-w-4xl w-full max-h-[90vh] overflow-y-auto shadow-2xl">
        {/* Close Button */}
        <button
          onClick={onClose}
          className="absolute top-4 right-4 z-10 bg-white rounded-full p-2 hover:bg-gray-100 transition-colors shadow-lg"
          aria-label="Close"
        >
          <X className="w-6 h-6 text-gray-700" />
        </button>
        
        {/* Product Image */}
        <ProductImage
          image={product.image}
          category={product.category}
          name={product.name}
          description={product.description}
          sizeRange={product.sizeRange}
        />
        
        {/* Product Details */}
        <ProductDetails productName={product.name} />
      </div>
    </div>
  );
};

export default ProductModal;
